      _initData();
    });
  }

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _filteredCurrenciesNotifier = ValueNotifier(<CurrencyModel>[]);
    _currencyListFuture = Future.value([]);
    // Запускаем загрузку из кэша через FutureBuilder (как в оригинале)
  }

